create or replace function public.ils_professional_assignment_mutation_commit(p_assignment_link_id uuid,p_operation text,p_to_status text) returns boolean language plpgsql volatile security definer set search_path=public as $$ declare v record; v_prev_hash text; v_event_hash text; begin if not public.ils_professional_assignment_mutation_gate(p_assignment_link_id,p_operation,p_to_status) then return false; end if; select l.id,l.work_item_id,l.work_stream,l.professional_user_id,l.link_status into v from public.ils_professional_work_assignment_links l where l.id=p_assignment_link_id and l.professional_user_id=auth.uid() for update; if not found then return false; end if; if not public.ils_professional_assignment_mutation_gate(v.id,p_operation,p_to_status) then return false; end if; select e.event_hash into v_prev_hash from public.ils_professional_assignment_mutation_event_chain e where e.assignment_link_id=v.id order by e.occurred_at desc,e.id desc limit 1; v_event_hash:=md5(coalesce(v_prev_hash,'')||'|'||v.id::text||'|'||v.work_item_id::text||'|'||v.work_stream||'|'||v.professional_user_id::text||'|'||p_operation||'|'||coalesce(v.link_status,'')||'|'||p_to_status||'|'||clock_timestamp()::text); update public.ils_professional_work_assignment_links set link_status=p_to_status,updated_at=now() where id=v.id and link_status=v.link_status; if not found then return false; end if; insert into public.ils_professional_assignment_mutation_audit(assignment_link_id,work_item_id,work_stream,professional_user_id,operation,from_status,to_status,decision,reason_code) values(v.id,v.work_item_id,v.work_stream,v.professional_user_id,p_operation,v.link_status,p_to_status,'ALLOW','MUTATION_COMMIT'); insert into public.ils_professional_assignment_mutation_event_chain(assignment_link_id,work_item_id,work_stream,professional_user_id,operation,from_status,to_status,decision,reason_code,event_hash,previous_event_hash) values(v.id,v.work_item_id,v.work_stream,v.professional_user_id,p_operation,v.link_status,p_to_status,'ALLOW','MUTATION_COMMIT',v_event_hash,v_prev_hash); return true; exception when unique_violation then return false; end; $$; revoke all on function public.ils_professional_assignment_mutation_commit(uuid,text,text) from public,anon; grant execute on function public.ils_professional_assignment_mutation_commit(uuid,text,text) to authenticated; create table if not exists public.ils_professional_assignment_mutation_commit_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_commit_tests enable row level security; alter table public.ils_professional_assignment_mutation_commit_tests force row level security; revoke all on public.ils_professional_assignment_mutation_commit_tests from anon,authenticated; insert into public.ils_professional_assignment_mutation_commit_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('GATE_REQUIRED','BLOCK_WITHOUT_AUTH_OR_VALID_ASSIGNMENT','BLOCK_WITHOUT_AUTH_OR_VALID_ASSIGNMENT',true,'Commit delegates to the existing mutation gate before changing state.'),('ROW_LOCK','SERIALIZED','SERIALIZED',true,'SELECT FOR UPDATE serializes competing mutations for the same assignment.'),('STALE_STATUS','BLOCK','BLOCK',true,'Update requires the observed from-status to remain current.'),('AUDIT_BEFORE_CHAIN','REQUIRED','REQUIRED',true,'Successful commit writes mutation audit and immutable event evidence.'),('CHAIN_PREVIOUS_HASH','LINKED','LINKED',true,'Latest prior event hash is carried into the new event.'),('DUPLICATE_HASH','BLOCK','BLOCK',true,'Unique event hash prevents exact duplicate event records.'),('NO_LIVE_ASSIGNMENT','PENDING_AUTH_E2E','PENDING_AUTH_E2E',true,'TEST currently has no live assignment/authenticated session; no fake commit executed.');